&lt;/li&gt;
&lt;li class=&quot;ck-list-marker-font-size ck-list-marker-color ck-list-marker-font-family&quot; data-list-item-id=&quot;e91b39dd3453c979c9f71a45d26b4bb9c&quot;&gt;
