&lt;/li&gt;
&lt;li class=&quot;ck-list-marker-font-size ck-list-marker-color ck-list-marker-font-family&quot; data-list-item-id=&quot;e4c11ed2cfb8c54c5bd537adbbda358ff&quot;&gt;
